@RunWith(MockitoJUnitRunner.class)
public class AbstractCommandLineRunner_setRunOptions_TriageGen0Test {

    private TestCommandLineRunner runner;
    private CommandLineConfig config;
    private CompilerOptions options;
    private DiagnosticGroups diagnosticGroups;

    // Concrete implementation for testing abstract class
    private static class TestCommandLineRunner extends AbstractCommandLineRunner {
        private final CommandLineConfig config;
        private final DiagnosticGroups diagnosticGroups;

        TestCommandLineRunner(CommandLineConfig config, DiagnosticGroups diagnosticGroups) {
            this.config = config;
            this.diagnosticGroups = diagnosticGroups;
        }

        @Override
        protected CommandLineConfig getCommandLineConfig() { return config; }
        @Override
        protected DiagnosticGroups getDiagnosticGroups() { return diagnosticGroups; }
        @Override
        protected Object createCompiler() { return null; }
        @Override
        protected Object createOptions() { return null; }
        @Override
        protected boolean isInTestMode() { return true; }
        @Override
        protected java.io.PrintStream getErrorPrintStream() { return null; }
        @Override
        protected java.io.OutputStream filenameToOutputStream(String fileName) throws IOException { return null; }
        @Override
        protected java.util.List<com.google.javascript.jscomp.JSSourceFile> createInputs(java.util.List<com.google.javascript.jscomp.JSSourceFile> files, boolean allowStdIn) { return null; }
        @Override
        protected void checkModuleName(String name) throws FlagUsageException {}
        @Override
        protected java.util.List<com.google.javascript.jscomp.JSSourceFile> createExterns() throws FlagUsageException, IOException { return null; }
        @Override
        protected int doRun() throws FlagUsageException, IOException { return 0; }
        @Override
        protected void initOptionsFromFlags(CompilerOptions options) {}
    }

    @Before
    public void setUp() {
        config = new CommandLineConfig();
        // Initialize defaults to avoid NullPointerException in method logic
        config.jscompError = CheckLevel.ERROR;
        config.jscompWarning = CheckLevel.WARNING;
        config.jscompOff = CheckLevel.OFF;
        config.define = Collections.emptyList();
        config.tweak = Collections.emptyList();
        config.tweakProcessing = false;
        config.closureEntryPoints = Collections.emptyList();
        config.manageClosureDependencies = false;
        config.jscompDevMode = false;
        config.codingConvention = null;
        config.summaryDetailLevel = null;
        config.jsOutputFile = "";
        config.createSourceMap = "";
        config.sourceMapDetailLevel = null;
        config.sourceMapFormat = null;
        config.variableMapInputFile = "";
        config.propertyMapInputFile = "";
        config.languageIn = "";
        config.acceptConstKeyword = false;

        diagnosticGroups = mock(DiagnosticGroups.class);
        runner = spy(new TestCommandLineRunner(config, diagnosticGroups));
        options = new CompilerOptions();

        // Mocking protected fields via reflection or behavior if possible, 
        // but here we assume the runner inherits/manages them.
        // Since we can't easily set protected fields in a spy without accessors, 
        // we rely on the fact that the method uses config and diagnosticGroups.
    }

    @Test
    public void testSetRunOptions_FullSuccess() throws Exception {
        config.jsOutputFile = "out.js";
        config.createSourceMap = "map.js.map";
        config.sourceMapDetailLevel = null;
        config.sourceMapFormat = null;
        config.languageIn = "ECMASCRIPT5";
        config.acceptConstKeyword = true;
        config.closureEntryPoints = Collections.singletonList(mock(com.google.javascript.jscomp.JSSourceFile.class));
        config.manageClosureDependencies = true;

        try (MockedStatic<VariableMap> mockedVariableMap = Mockito.mockStatic(VariableMap.class)) {
            VariableMap mockMap = mock(VariableMap.class);
            mockedVariableMap.when(() -> VariableMap.load(any())).thenReturn(mockMap);
            when(mockMap.toBytes()).thenReturn(new byte[]{1, 2, 3});

            config.variableMapInputFile = "var.map";
            config.propertyMapInputFile = "prop.map";

            runner.setRunOptions(options);

            assertThat(options.jsOutputFile).isEqualTo("out.js");
            assertThat(options.sourceMapOutputPath).isEqualTo("map.js.map");
            assertThat(options.languageIn).isEqualTo(CompilerOptions.LanguageMode.ECMASCRIPT5);
            assertThat(options.acceptConstKeyword).isTrue();
            assertThat(options.manageClosureDependencies).isTrue();
            assertThat(options.inputVariableMapSerialized).isEqualTo(new byte[]{1, 2, 3});
        }
    }

    @Test
    public void testSetRunOptions_LanguageModes() throws Exception {
        // Test ES5 Strict
        config.languageIn = "ECMASCRIPT5_STRICT";
        runner.setRunOptions(options);
        assertThat(options.getLanguageMode()).isEqualTo(CompilerOptions.LanguageMode.ECMASCRIPT5);

        // Test ES5
        config.languageIn = "ES5";
        runner.setRunOptions(options);
        assertThat(options.getLanguageMode()).isEqualTo(CompilerOptions.LanguageMode.ECMASCRIPT5);

        // Test ES3
        config.languageIn = "ES3";
        runner.setRunOptions(options);
        assertThat(options.getLanguageMode()).isEqualTo(CompilerOptions.LanguageMode.ECMASCRIPT3);
    }

    @Test(expected = FlagUsageException.class)
    public void testSetRunOptions_UnknownLanguage() throws Exception {
        config.languageIn = "INVALID_LANG";
        runner.setRunOptions(options);
    }

    @Test
    public void testSetRunOptions_ClosureEntryPoints() throws Exception {
        com.google.javascript.jscomp.JSSourceFile entryPoint = mock(com.google.javascript.jscomp.JSSourceFile.class);
        config.closureEntryPoints = Collections.singletonList(entryPoint);

        runner.setRunOptions(options);
        // Note: options.setManageClosureDependencies is called if size > 0
        // We verify the logic path by ensuring no exception and checking state if possible
    }

    @Test
    public void testSetRunOptions_MinimalConfig() throws Exception {
        // Test branches where if statements are false (empty strings/lists)
        config.jsOutputFile = "";
        config.createSourceMap = "";
        config.languageIn = "";
        config.variableMapInputFile = "";
        config.propertyMapInputFile = "";
        config.closureEntryPoints = Collections.emptyList();

        runner.setRunOptions(options);

        assertThat(options.jsOutputFile).isNull(); // Assuming it was null initially
        assertThat(options.sourceMapOutputPath).isNull();
    }

    @Test
    public void testSetRunOptions_DiagnosticGroups() throws Exception {
        runner.setRunOptions(options);
        verify(diagnosticGroups).setWarningLevels(options, config.jscompError, CheckLevel.ERROR);
        verify(diagnosticGroups).setWarningLevels(options, config.jscompWarning, CheckLevel.WARNING);
        verify(diagnosticGroups).setWarningLevels(options, config.jscompOff, CheckLevel.OFF);
    }
}
